\begin{tikzpicture}[scale=1.0, every node/.style={font=\small}, >=stealth]
  % rod base
  \draw[thick] (0,0) rectangle (8,0.55);

  % simple density shading by strips
  \foreach \i in {0,...,15} {
    \pgfmathsetmacro{\shade}{8+2*\i}
    \fill[gray!\shade] ({0.5*\i},0) rectangle ({0.5*(\i+1)},0.55);
  }
  \draw[thick] (0,0) rectangle (8,0.55);

  % axis
  \draw[->, thick] (-0.3,-0.55) -- (8.6,-0.55) node[right] {\(x\)};
  \foreach \x/\lab in {0/0,4/2,8/4} {
    \draw[thick] (\x,-0.45) -- (\x,-0.65);
    \node[below] at (\x,-0.65) {\(\lab\)};
  }

  % center of mass marker
  \draw[very thick, ->] (4.67,1.35) -- (4.67,0.65);
  \node[above] at (4.67,1.35) {\(\bar x=\frac73\)};

  \node at (4,0.28) {density increases};
\end{tikzpicture}

\begin{tikzpicture}[scale=2.15, every node/.style={font=\small}, >=stealth]
  % axes
  \draw[->, thick] (-0.2,0) -- (2.6,0) node[right] {\(x\)};
  \draw[->, thick] (0,-0.2) -- (0,2.45) node[above] {\(y\)};

  % triangle
  \fill[gray!15] (0,0) -- (2,0) -- (2,2) -- cycle;

  % vertical slice fill
  \fill[gray!45] (1.25,0) -- (1.32,0) -- (1.32,1.32) -- (1.25,1.25) -- cycle;

  \draw[very thick] (0,0) -- (2,2);
  \draw[very thick] (2,0) -- (2,2);
  \draw[very thick] (0,0) -- (2,0);

  % vertical slice borders
  \draw[thick] (1.25,0) -- (1.25,1.25);
  \draw[thick] (1.32,0) -- (1.32,1.32);

  % slice height dimension
  \draw[<->, thick] (1.4,1.32) -- (1.4,0) node[midway, right=3pt] {slice height \(x\)};

  % center of mass
  \fill (1.333,0.667) circle (1.3pt);
  \node[anchor=east] at (1.30,0.67) {\(\left(\frac43,\frac23\right)\)};

  % labels
  \node[below] at (2,0) {\(2\)};
  \node[left] at (0,2) {\(2\)};
  \node[anchor=west] at (0.7,1.55) {\(y=x\)};
\end{tikzpicture}
